<script setup lang="ts">
import Modal from "@papilio/ui/Modal.vue";
import { computed, onUnmounted, ref, watch } from "vue";
import { useAuth } from "@papilio/auth";
import { item, query, request, type Page, type SupportTicket, type SupportMessage, type SupportHistory, type SupportAvailability, type SupportStatus } from "@papilio/api";
import { faDate, faNumber } from "@papilio/ui";
const props=defineProps<{audience:"admin"|"customer";customerId?:number;subscriptionId?:number;topupId?:number;ticketId?:number}>();const auth=useAuth();
const prefix=computed(()=>`/v1/${props.audience}/support`);const rows=ref<SupportTicket[]>([]);const q=ref("");const status=ref("");const page=ref(1);const pages=ref(1);const total=ref(0);const selected=ref<SupportTicket|null>(null);const policy=ref<SupportAvailability|null>(null);
const loading=ref(false);const selecting=ref(false);const busy=ref(false);const error=ref("");const notice=ref("");const messages=ref<SupportMessage[]>([]);const history=ref<SupportHistory[]>([]);const messagePage=ref(1);const messagePages=ref(1);const historyPage=ref(1);const historyPages=ref(1);const threadLoading=ref(false);const threadError=ref("");
const subject=ref("");const body=ref("");const replyBody=ref("");const reason=ref("");const nextStatus=ref<SupportStatus>("closed");const createKey=ref(crypto.randomUUID());const replyKey=ref(crypto.randomUUID());let listVersion=0;let selectionVersion=0;let threadVersion=0;
const labels:Record<SupportStatus,string>={open:"Pending Support",waiting_customer:"Pending Customer",closed:"Closed"};
const createOpen=ref(false),draftCustomer=ref<number|undefined>();
function startCreate():void{if(busy.value||selecting.value||!mayCreate.value)return;if(draftCustomer.value===undefined)draftCustomer.value=creationCustomer.value;createOpen.value=true;}
const creationCustomer=computed(()=>props.customerId??selected.value?.customer_id);
const mayCreate=computed(()=>policy.value?.capacity_valid&&policy.value.new_tickets_enabled&&(props.audience==="customer"||auth.can("support","create")&&creationCustomer.value!==undefined));
const mayReply=computed(()=>policy.value?.capacity_valid&&(props.audience==="customer"?policy.value.customer_replies_enabled:auth.can("support","update")&&policy.value.staff_replies_enabled)&&(selected.value?.status!=="closed"||policy.value.closed_reply_mode==="reopen"));
const mayChange=computed(()=>props.audience==="admin"?auth.can("support","update"):Boolean(selected.value?.status==="closed"?policy.value?.customer_reopen_enabled:policy.value?.customer_closure_enabled));
function characterCount(value:string):number{return Array.from(value).length;}
function validMessage(value:string):boolean{return Boolean(policy.value&&characterCount(value)<=policy.value.max_message_chars);}
function fail(cause:unknown):string{return cause instanceof Error?cause.message:"The operation failed. Please try again.";}
async function load():Promise<void>{const version=++listVersion;loading.value=true;error.value="";try{const [result,settings]=await Promise.all([request<Page<SupportTicket>>(`${prefix.value}?${query({q:q.value,status:status.value||undefined,page:page.value,customer_id:props.audience==="admin"?props.customerId:undefined})}`),item<SupportAvailability>(`${prefix.value}/policy`)]);if(version!==listVersion)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;policy.value=settings;}catch(cause){if(version===listVersion)error.value=fail(cause);}finally{if(version===listVersion)loading.value=false;}}
async function loadThread():Promise<void>{const row=selected.value;if(!row)return;const version=++threadVersion;threadLoading.value=true;threadError.value="";try{const [msgs,audit]=await Promise.all([request<Page<SupportMessage>>(`${prefix.value}/${row.id}/messages?${query({page:messagePage.value})}`),request<Page<SupportHistory>>(`${prefix.value}/${row.id}/history?${query({page:historyPage.value})}`)]);if(version!==threadVersion||selected.value?.id!==row.id)return;messages.value=msgs.data;messagePages.value=msgs.meta.pager?.total_pages??1;history.value=audit.data;historyPages.value=audit.meta.pager?.total_pages??1;}catch(cause){if(version===threadVersion)threadError.value=fail(cause);}finally{if(version===threadVersion)threadLoading.value=false;}}
async function select(row:Pick<SupportTicket,"id">,preserve=false):Promise<void>{if(busy.value||selecting.value)return;const version=++selectionVersion;selecting.value=true;error.value="";try{const fresh=await item<SupportTicket>(`${prefix.value}/${row.id}`);if(version!==selectionVersion)return;selected.value=fresh;if(!preserve){replyBody.value="";reason.value="";replyKey.value=crypto.randomUUID();nextStatus.value=fresh.status==="closed"?"open":"closed";messagePage.value=1;historyPage.value=1;messages.value=[];history.value=[];}void loadThread();if(preserve)notice.value="Current ticket loaded. Your reply and status drafts are retained.";}catch(cause){if(version===selectionVersion)error.value=fail(cause);}finally{if(version===selectionVersion)selecting.value=false;}}
async function create():Promise<void>{if(busy.value||selecting.value||!mayCreate.value||!validMessage(body.value)||characterCount(subject.value)>100)return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{const result=await item<SupportTicket>(prefix.value,"POST",{request_key:createKey.value,subject:subject.value,body:body.value,subscription_id:props.subscriptionId,topup_id:props.topupId,...(props.audience==="admin"?{customer_id:draftCustomer.value}:{})});if(stamp!==selectionVersion)return;selected.value=result;subject.value="";body.value="";createKey.value=crypto.randomUUID();replyBody.value="";replyKey.value=crypto.randomUUID();reason.value="";nextStatus.value=result.status==="closed"?"open":"closed";messagePage.value=1;historyPage.value=1;createOpen.value=false;draftCustomer.value=undefined;notice.value="Ticket created.";await load();await loadThread();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
async function reply():Promise<void>{const row=selected.value;if(!row||busy.value||selecting.value||!mayReply.value||!validMessage(replyBody.value))return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{const result=await item<SupportTicket>(`${prefix.value}/${row.id}/messages`,"POST",{request_key:replyKey.value,expected_revision:row.revision,body:replyBody.value});if(stamp!==selectionVersion)return;selected.value=result;replyBody.value="";replyKey.value=crypto.randomUUID();notice.value="Reply recorded.";messagePage.value=1;historyPage.value=1;await load();await loadThread();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
async function change():Promise<void>{const row=selected.value;if(!row||busy.value||selecting.value||!mayChange.value)return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{const result=await item<SupportTicket>(`${prefix.value}/${row.id}/state`,"PUT",{expected_revision:row.revision,status:nextStatus.value,reason:reason.value});if(stamp!==selectionVersion)return;selected.value=result;reason.value="";notice.value="Ticket status saved.";await load();await loadThread();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
watch([q,status],()=>{page.value=1;void load();});onUnmounted(()=>{selectionVersion++;listVersion++;threadVersion++;});
watch(()=>[props.audience,props.customerId,props.subscriptionId,props.topupId,props.ticketId],()=>{selectionVersion++;threadVersion++;selected.value=null;createOpen.value=false;draftCustomer.value=undefined;subject.value="";body.value="";page.value=1;createKey.value=crypto.randomUUID();void load();if(props.ticketId!==undefined)void select({id:props.ticketId});},{immediate:true});
</script>
<template>
<p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p><p v-if="policy&&!policy.capacity_valid" class="message error">The saved policy exceeds capacity. Reading and closing tickets remain available.</p>
<div :class="{split:!!selected}"><section class="card card-pad"><h2>Tickets</h2><div class="form-grid"><label class="field"><span>Search subject</span><input v-model="q" maxlength="100" :disabled="busy" /></label><label class="field"><span>Ticket status</span><select v-model="status" aria-label="Ticket status" :disabled="busy"><option value="">All</option><option v-for="(label,value) in labels" :key="value" :value="value">{{label}}</option></select></label><button class="btn secondary" :disabled="loading||busy" @click="load">Refresh tickets</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Subject</th><th v-if="audience==='admin'">Customer</th><th>Status</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" :class="{'selected-row':selected?.id===row.id}" tabindex="0" @click="select(row)" @keydown.enter="select(row)"><td>{{row.subject}} · {{faNumber(row.id)}}</td><td v-if="audience==='admin'">{{faNumber(row.customer_id)}}</td><td>{{labels[row.status]}}</td></tr></tbody></table></div><p v-if="loading">Loading…</p><p v-else-if="!rows.length&&!error">No tickets found.</p><div class="pager"><button :disabled="page<=1||loading||busy" @click="page--;load()">‹</button><span>{{faNumber(page)}} · {{faNumber(total)}} tickets</span><button :disabled="page>=pages||loading||busy" @click="page++;load()">›</button></div></section>
<div class="stack"><section v-if="selected" class="card card-pad stack"><h2>{{selected.subject}}</h2><p>{{labels[selected.status]}} · Revision {{faNumber(selected.revision)}} · {{faDate(selected.updated_at)}}</p><p v-if="selected.subscription_id">Related subscription: {{faNumber(selected.subscription_id)}}</p><p v-if="selected.topup_id">Related payment: {{faNumber(selected.topup_id)}}</p><p v-if="threadError" class="message error">{{threadError}}</p><p v-if="threadLoading">Loading conversation…</p><button class="btn secondary" :disabled="busy||selecting" @click="select(selected,true)">Refresh and retain draft</button><article v-for="row in messages" :key="row.id" class="ticket-message"><strong>{{row.author_kind==='staff'?'Support':'Customer'}} · {{faDate(row.created_at)}}</strong><p class="message-body">{{row.body}}</p><small v-if="audience==='admin'&&row.staff_id!=null">Staff ID: {{faNumber(row.staff_id)}}</small><small v-else-if="audience==='admin'&&row.customer_id!=null">Customer ID: {{faNumber(row.customer_id)}}</small></article><div class="pager"><button :disabled="messagePage<=1||threadLoading" @click="messagePage--;loadThread()">‹</button><span>Messages · {{faNumber(messagePage)}}</span><button :disabled="messagePage>=messagePages||threadLoading" @click="messagePage++;loadThread()">›</button></div>
<form v-if="mayReply" class="form-grid" @submit.prevent="reply"><label class="field"><span>Reply message</span><textarea aria-label="Reply message" v-model="replyBody" required :disabled="busy||selecting" /><small>{{faNumber(characterCount(replyBody))}} / {{faNumber(policy!.max_message_chars)}}</small></label><button class="btn" :disabled="busy||selecting||!replyBody.trim()||!validMessage(replyBody)">Send reply</button></form><p v-else-if="policy" class="hint-box">Replies are unavailable under the current status or policy. The conversation is retained.</p>
<form v-if="mayChange" class="form-grid" @submit.prevent="change"><label class="field"><span>New ticket status</span><select v-model="nextStatus" aria-label="New ticket status" :disabled="busy||selecting"><option value="open" :disabled="audience==='customer'&&!policy?.customer_reopen_enabled">Pending Support</option><option v-if="audience==='admin'" value="waiting_customer">Pending Customer</option><option value="closed" :disabled="audience==='customer'&&!policy?.customer_closure_enabled">Closed</option></select></label><label class="field"><span>Status change reason</span><input v-model="reason" minlength="3" maxlength="250" required :disabled="busy||selecting" /></label><button class="btn secondary" :disabled="busy||selecting||reason.trim().length<3">Save ticket status</button></form>
<details><summary>Status history</summary><div v-for="row in history" :key="row.id" class="hint-box"><p>{{labels[row.previous_status]}} → {{labels[row.status]}} · {{faNumber(row.revision)}}</p><p>{{row.reason}} · {{row.author_kind==='staff'?'Support':'Customer'}} · {{faDate(row.created_at)}}</p></div><div class="pager"><button :disabled="historyPage<=1||threadLoading" @click="historyPage--;loadThread()">‹</button><span>{{faNumber(historyPage)}}</span><button :disabled="historyPage>=historyPages||threadLoading" @click="historyPage++;loadThread()">›</button></div></details></section>
<button v-if="mayCreate" class="btn" :disabled="busy||selecting" @click="startCreate">+ Create ticket</button><Modal v-if="mayCreate" v-model="createOpen" title="Create support ticket" :busy="busy" wide><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="audience==='admin'">For customer {{faNumber(draftCustomer!)}}</p><p v-if="subscriptionId">About subscription {{faNumber(subscriptionId)}}</p><p v-if="topupId">About payment {{faNumber(topupId)}}</p><form class="form-grid" @submit.prevent="create"><label class="field"><span>Ticket subject</span><input v-model="subject" required :disabled="busy||selecting" /></label><label class="field"><span>Message</span><textarea aria-label="Message" v-model="body" required :disabled="busy||selecting" /><small>{{faNumber(characterCount(body))}} / {{faNumber(policy!.max_message_chars)}}</small></label><button class="btn" :disabled="busy||selecting||!subject.trim()||characterCount(subject)>100||!body.trim()||!validMessage(body)">Create ticket</button></form></Modal><p v-else-if="audience==='admin'&&auth.can('support','create')&&!creationCustomer" class="hint-box">Open a customer record or select a ticket to retain the customer for a new request.</p>
</div></div>
</template>
<style scoped>.ticket-message{padding:14px;border:1px solid var(--line);border-radius:12px;min-width:0}.message-body{white-space:pre-wrap;overflow-wrap:anywhere}.ticket-message strong{font-size:13px}textarea{min-height:130px;resize:vertical}.stack{min-width:0}</style>
